import {jest} from '@jest/globals';
import {ToolRegistry} from './registry.js';

// specs/hal-engine-tool-input-validation/spec.md#10
it('caches dynamic validators by schema reference', async () => {
  const registry = new ToolRegistry();
  const compile = jest.spyOn(registry['validator'], 'compile');
  const schemas = [
    {type: 'object', required: ['location']},
    {type: 'object', required: ['unit']},
  ];
  let current = 0;
  registry.register(() => ({name: 'weather', description: 'Weather', inputSchema: schemas[current]}), async () => 'ok');

  expect((await registry.execute('weather', {})).result).toContain('location');
  await registry.execute('weather', {location: 'Paris'});
  current = 1;
  expect((await registry.execute('weather', {})).result).toContain('unit');
  await registry.execute('weather', {unit: 'C'});
  current = 0;
  await registry.execute('weather', {location: 'Paris'});
  expect(compile).toHaveBeenCalledTimes(2);
});
EOF
timeout 300 npm test -- --runInBand --runTestsByPath src/orchestration/tools/registry.cache.test.ts"

